// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/.well-known/oauth-authorization-server", wrapper.GetAuthServerMetadata)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/.well-known/oauth-protected-resource", wrapper.GetResourceMetadata)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/.well-known/oauth-protected-resource/{resource_path}", wrapper.GetSpecificResourceMetadata)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/{register_client_endpoint}", wrapper.RegisterOauthClient)

	return m
}

